 static FieldInfo FindField(Type type,string name){for(var scan=type;scan!=null;scan=scan.BaseType){var field=scan.GetField(name,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.DeclaredOnly);if(field!=null)return field;}return null;}
