 static byte[] PackedBytes(string raw){if(raw==null||raw.Length==0||raw.Length>4194304||raw.Length%2!=0||raw.Any(c=>!(c>='0'&&c<='9'||c>='a'&&c<='f')))throw new NotSupportedException("Bounded exact Unity byte payload required");var bytes=new byte[raw.Length/2];for(int i=0;i<bytes.Length;i++){char high=raw[2*i],low=raw[2*i+1];bytes[i]=(byte)(((high<='9'?high-'0':high-'a'+10)<<4)|(low<='9'?low-'0':low-'a'+10));}return bytes;}
 static JArray PackedSourceArray(Type arrayType,string raw){Type element=arrayType.GetElementType();if((!element.IsEnum&&element!=typeof(byte))||raw==null||raw.Length==0||raw.Length>4194304||raw.Length%2!=0||raw.Any(c=>!(c>='0'&&c<='9'||c>='a'&&c<='f'))||!BitConverter.IsLittleEndian)throw new NotSupportedException("Exact bounded Unity packed enum array required");Type primitive=element.IsEnum?Enum.GetUnderlyingType(element):element;int width=System.Runtime.InteropServices.Marshal.SizeOf(primitive);if(raw.Length%(2*width)!=0)throw new NotSupportedException("Packed enum width mismatch");var bytes=new byte[raw.Length/2];for(int i=0;i<bytes.Length;i++)bytes[i]=Convert.ToByte(raw.Substring(i*2,2),16);var result=new JArray();for(int i=0;i<bytes.Length;i+=width){object number=primitive==typeof(byte)?(object)bytes[i]:primitive==typeof(sbyte)?(sbyte)bytes[i]:primitive==typeof(short)?BitConverter.ToInt16(bytes,i):primitive==typeof(ushort)?BitConverter.ToUInt16(bytes,i):primitive==typeof(int)?BitConverter.ToInt32(bytes,i):primitive==typeof(uint)?BitConverter.ToUInt32(bytes,i):primitive==typeof(long)?BitConverter.ToInt64(bytes,i):primitive==typeof(ulong)?BitConverter.ToUInt64(bytes,i):throw new NotSupportedException("Packed enum primitive");result.Add(JToken.FromObject(number));}return result;}
 object Read(JToken token,Type type,int depth){if(depth>32)throw new NotSupportedException("Config depth bound");if(token.Type==JTokenType.Null){if(type.IsValueType)throw new NotSupportedException("Value type config null");return null;}
  if(token is JObject reference&&reference["fileID"]!=null){long file=(long)reference["fileID"];if(file==0){if(type.IsValueType)throw new NotSupportedException("Null source reference for value type");return null;}if(reference["guid"]==null||reference.Properties().Any(p=>p.Name!="fileID"&&p.Name!="guid"&&p.Name!="type"))throw new NotSupportedException("Exact source reference required");return Resolve((string)reference["guid"],type,depth+1);}
  if(type.FullName=="UnityEngine.AddressableAssets.AssetReference"){var row=(JObject)token;if(row.Properties().Any(p=>p.Name!="m_AssetGUID"&&p.Name!="m_SubObjectName"&&p.Name!="m_SubObjectType"&&p.Name!="m_SubObjectGUID"&&p.Name!="m_EditorAssetChanged")||!string.IsNullOrEmpty((string)row["m_SubObjectName"])||!string.IsNullOrEmpty((string)row["m_SubObjectType"])||!string.IsNullOrEmpty((string)row["m_SubObjectGUID"]))throw new NotSupportedException("Only source root asset reference metadata admitted");return Activator.CreateInstance(type,new object[]{(string)row["m_AssetGUID"]});}
  if(type.FullName=="UnityEngine.Vector2Int"){var vector=token as JObject??throw new NotSupportedException("Source Vector2Int object");if(vector.Properties().Select(p=>p.Name).OrderBy(x=>x).SequenceEqual(new[]{"x","y"})==false)throw new NotSupportedException("Exact Vector2Int axes required");return Activator.CreateInstance(type,new object[]{checked((int)vector["x"]),checked((int)vector["y"])});}
  if(type==typeof(string)){if(token.Type!=JTokenType.String)throw new NotSupportedException("Source string type");return(string)token;}if(type==typeof(bool)){if(token.Type==JTokenType.Boolean)return(bool)token;if(token.Type==JTokenType.Integer&&((long)token==0||(long)token==1))return(long)token==1;throw new NotSupportedException("Source bool type");}
