  if(type.IsPrimitive){if(token.Type!=JTokenType.Integer&&token.Type!=JTokenType.Float)throw new NotSupportedException("Source scalar type");var converted=token.ToObject(type);if(converted is float f&&(float.IsNaN(f)||float.IsInfinity(f))||converted is double d&&(double.IsNaN(d)||double.IsInfinity(d)))throw new NotSupportedException("Finite source config scalar required");return converted;}
  if(type.IsGenericType&&type.GetGenericTypeDefinition()==typeof(List<>)){var items=token as JArray??throw new NotSupportedException("Source collection type="+type+" token="+token.Type+" value="+token.ToString());if(items.Count>4096)throw new NotSupportedException("Config list bound");var list=(System.Collections.IList)Activator.CreateInstance(type);foreach(var item in items)list.Add(Read(item,type.GetGenericArguments()[0],depth+1));return list;}
  if(type.IsArray){var items=token as JArray??throw new NotSupportedException("Source collection type="+type+" token="+token.Type+" value="+token.ToString());if(items.Count>4096)throw new NotSupportedException("Config array bound");Type element=type.GetElementType();var result=Array.CreateInstance(element,items.Count);for(int i=0;i<items.Count;i++)result.SetValue(Read(items[i],element,depth+1),i);return result;}
  if(!type.IsValueType&&type.Namespace!="Game.Configs")throw new NotSupportedException("Source metadata object outside profile: "+type.FullName);object boxed=Activator.CreateInstance(type,true);foreach(var item in((JObject)token).Properties()){var field=FindField(type,item.Name);if(field==null||field.IsStatic||field.IsInitOnly)throw new NotSupportedException("Unknown source value field "+type.Name+"."+item.Name);field.SetValue(boxed,Read(item.Value,field.FieldType,depth+1));}return boxed;
 }
